-- The Year 7/8 Number & Algebra question bank: 200 questions across 12 topics.
--
-- Generated by `python3 scripts/generate_bank_migration.py --version 11` from
-- content/bank/*.json, and checked by `python3 content/render.py --check`. Do not edit it by hand:
-- edit the JSON and generate the next migration.
--
-- Insert-only. Nothing here updates or deletes a question, an option or a topic's questions, so
-- applying it can never overwrite a question a teacher has edited. It runs after
-- V10__retire_prototype_question_bank.sql, which clears the prototype bank out of the way;
-- running the sweep after this migration would retire this bank too.
--
-- Every wrong option carries the misconception code it was written to catch, in
-- answer_options.misconception_code (V9). There are 568 of them. The register that defines the
-- codes is content/misconceptions.json; the codes are stored so a wrong answer can be read as a
-- named error rather than only as a wrong number.
--
-- Inserted as origin = 'SEED': this is the bank the app ships with, as opposed to content a
-- teacher writes ('AUTHORED') or imports ('IMPORTED').

-- Topics. `fractions` already exists - it held the prototype's combined Fractions, Decimals &
-- Percentages topic - so it is repurposed for this bank's Fractions topic, keeping its slug and id
-- so any recorded session still resolves. Its old name is replaced only if nobody has changed it.
on conflict(slug) do nothing;

-- The prototype row, repurposed. Guarded on the old name so a teacher's rename is
-- not overwritten.
update topics set name = 'Fractions', description = 'Equivalent fractions, comparing, and adding, subtracting, multiplying and dividing fractions.', sort_order = 5
 where slug = 'fractions' and name = 'Fractions, Decimals & Percentages';

-- The id of the question just inserted, one row at a time. Cleared before each capture, so
-- the subquery below can only ever match one row.
create temp table seed_question (id integer);

-- pv-tick-compare-1  (band 2, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', '0.5 is five tenths and 0.45 is only four tenths, so 0.5 is larger however many digits follow. The zero in 0.405 is a placeholder in the hundredths column, so 0.405 is smaller than 0.45. On a number line −7 is to the left of −3, and −2.5 is to the left of −2.05, so both ''greater than'' claims are the wrong way round. 0.09 is nine hundredths and 0.1 is ten hundredths, so 0.1 is larger.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-largest-decimal  (band 1, single_choice)
values ((select id from topics where slug = 'place-value'), 'Which of these numbers is the largest?', 'Compare the tenths first: 0.5 has five tenths and the others have four, four and zero, so 0.5 is largest. Counting digits instead of comparing place value makes 0.405 look biggest because it is longest. Reading 0.049 as ''forty-nine'' makes it look big, but the 4 is in the hundredths column and there are no tenths at all.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-tick-zero-placeholder  (band 2, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', 'A zero in a decimal holds a column open. In 0.405 the zero is in the hundredths column, so the number is four tenths and five thousandths — smaller than 0.45. In 3.05 the zero is in the tenths column, so there are no tenths, which is not the same as 3.5. A zero after the last digit, as in 0.30 or 3.50, changes nothing. In 0.07 the 7 is in the hundredths column, so it is 7 hundredths, not 7 tenths.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-tick-negative-order  (band 1, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', 'On a number line, further left is smaller. −7 is left of −3 and −10 is left of −4, so ''−10 > −4'' is backwards. The larger the digit after the minus sign, the smaller the number: −2 is greater than −5, and −0.5 is greater than −1. −2.5 is left of −2.05, so −2.5 is the smaller number, not the greater. Zero sits to the right of every negative number.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-tick-column-names  (band 2, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', 'The columns after the decimal point are tenths, then hundredths, then thousandths. In 4.782 the 7 is in the tenths column, the 8 is in the hundredths column and the 2 is in the thousandths column, so the second and fourth claims have the columns wrong. In 5.06 the 6 is in the hundredths column. 0.7 is seven tenths, and seven tenths is the same as seventy hundredths.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-tick-power-of-ten  (band 2, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', 'Multiplying by 10, 100 or 1000 moves every digit that many columns to the left; dividing moves them right. So 0.4 × 100 = 40 and 5.2 ÷ 10 = 0.52. Writing 0.400 for 0.4 × 100 just adds zeros and leaves the value unchanged. 5.2 ÷ 10 is not 5.20. Multiplying by 1000 moves the digits three columns, so 6 × 1000 is 6000, not 600.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-numbers-between  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'How many numbers are there strictly between 0.4 and 0.5?', 'Between any two different decimals there is always another one: 0.45 sits between them, but so do 0.41, 0.401 and 0.4001, and you can keep going for ever. Counting only the tenths or only the hundredths makes it look as though there is nothing or only one.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-order-decimals  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'Write 0.6, 0.06, 0.66 and 0.606 in order, smallest first. Which order is correct?', 'Line the numbers up by place value: 0.060, 0.600, 0.606, 0.660. Comparing tenths first gives 0.06 smallest and both 0.6 and 0.606 with six tenths; 0.606 has the extra six thousandths, so 0.66 (six tenths and six hundredths) is largest. Putting 0.6 first counts digits instead of comparing place value. Putting 0.606 last reads it as 606 against 66.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-tick-negative-decimals  (band 4, multi_select)
values ((select id from topics where slug = 'place-value'), 'Tick every statement that is true.', 'More negative means smaller, so −3.5 is left of −3.05 and −4.2 is left of −4.02; both claims that they are greater are backwards. −0.5 is left of −0.45, so it is smaller. −8 is greater than −12 because it is less negative. Every negative temperature is colder than every positive one, and −6 is colder than −4. No negative number is greater than zero.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- pv-digit-value-074  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'In the number 12.074, what is the value of the digit 7?', 'After the decimal point the columns are tenths, hundredths, thousandths. There is a 0 in the tenths column, so the 7 occupies the hundredths column and is worth 7 hundredths. Calling it 7 tenths skips the zero; calling it 7 thousandths moves it one column too far right; 70 hundredths would be seven tenths.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-error-power-ten  (band 3, single_choice)
values ((select id from topics where slug = 'place-value'), 'Ben works out 0.4 × 100 and writes the answer 0.400. What has he done?', 'Multiplying by 100 moves each digit two columns to the left, so 0.4 × 100 = 40. Ben has kept the digits where they are and written extra zeros, which leaves the value unchanged. Multiplying by 10 would give 4, not 0.400, and dividing by 100 would give 0.004. The answer has not been rounded, it has been left alone.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- pv-bridge-run-distance  (band 2, single_choice)
values ((select id from topics where slug = 'place-value'), 'Dan runs 0.5 km on Monday and 0.45 km on Tuesday. On which day did he run further?', '0.5 is 0.50, which is five tenths; 0.45 is four tenths and five hundredths. Comparing the tenths first, Monday is further. Comparing the digits 45 and 5 treats a hundredths count against a tenths count. Having more digits does not make a decimal larger — 0.45 is 0.450, still less than 0.5. The two distances are not the same.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
