-- prop-tick-factor-multiple-1  (band 2, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'A factor divides into a number exactly; a multiple is what you get from its times table. 4 divides into 12, so 4 is a factor of 12 and 12 is a multiple of 4 — the second claim turns that round. Multiples carry on for ever, so no number has a fixed number of them. A prime has exactly two factors; 1 has only one factor, itself, so it is not prime. 2 is prime because its only factors are 1 and 2.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-tick-prime-definition  (band 2, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'A prime number has exactly two factors: 1 and itself. 1 has one factor, so it fails. 9 = 3 × 3 and 51 = 3 × 17, so both are composite. 2 has factors 1 and 2 only and is prime, which is why ''every prime is odd'' is false. 29 has no factor other than 1 and 29.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-factor-or-multiple  (band 1, single_choice)
values ((select id from topics where slug = 'properties-of-number'), 'Which statement is true?', '6 divides into 18 exactly (18 ÷ 6 = 3), so 6 is a factor of 18. A multiple of 18 is at least 18, so 6 cannot be a multiple of 18. 18 is bigger than 6, so it cannot divide into 6, and 36 is bigger than 18, so it cannot divide into 18 either.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- prop-tick-multiples-for-ever  (band 1, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'The multiples of 7 are 7, 14, 21, and so on without end: after 84 comes 91. Nothing stops them, so the idea of a last multiple or a fixed count of twelve comes from the times table grid rather than from the numbers. 70 = 7 × 10, so 70 is a multiple of 7 and 7 is a factor of 70 — the two are not interchangeable.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-tick-hcf-lcm-1  (band 3, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'The highest common factor is the biggest number that divides into both, so it can never be bigger than either number — 12 cannot be the HCF of 4 and 6. The lowest common multiple is the smallest number both divide into, so it can never be smaller than either — 1 cannot be the LCM of 8 and 9. Multiplying the two numbers gives 24 for 4 and 6, which is a common multiple but not the lowest. 8 and 9 share no factor other than 1, and their lowest common multiple is 72.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-tick-squares-cubes  (band 2, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'A square multiplies the number by itself, so 5² = 5 × 5 = 25. A cube multiplies it by itself twice, so 5³ = 5 × 5 × 5 = 125. Doubling or tripling the base instead (5 × 2, 5 × 3) gives 10 and 15. A square root asks which number squares to give the value: 4 × 4 = 16, so √16 = 4; halving gives 8, which would square to 64.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-prime-factorisation  (band 3, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'A prime factorisation keeps going until every factor is prime: each of 2, 3 and 5 has no factors but 1 and itself. 4 = 2 × 2, 9 = 3 × 3 and 12 = 2 × 2 × 3, so those factorisations have stopped too early. The product is right in every false option; it is the unfinished factor that is wrong.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- prop-tick-factor-pairs  (band 3, multi_select)
values ((select id from topics where slug = 'properties-of-number'), 'Tick every statement that is true.', 'Factors come in pairs that multiply to the number: 1 × 12, 2 × 6 and 3 × 4, so 12 has six factors, not five. 15 pairs as 1 × 15 and 3 × 5, giving four factors. Only prime numbers have exactly two factors; 12 has six and 1 has one. 15 is larger than 3, so 15 cannot divide into 3 — a factor must divide into the number, not the other way round.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
