-- int-retention-sign-and-facts  (band 1, multi_select)
values ((select id from topics where slug = 'integers-and-decimals'), 'Tick every statement that is true.', 'Every negative number is less than every positive one, so −3 < 2 and 2 > −3. The facts 5 + 3 = 8 and 10 ÷ 2 = 5 are correct. But 3 − 5 is not 5 − 3: subtracting the larger number from the smaller gives −2, not 2. In the same way 2 − 6 = −4, not 4.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- int-tick-multiplies-bigger  (band 2, multi_select)
values ((select id from topics where slug = 'integers-and-decimals'), 'Tick every statement that is true.', 'Multiplying by a number smaller than 1 makes the answer smaller: 10 × 0.9 = 9. Multiplying by a number bigger than 1 makes it bigger: 10 × 1.5 = 15. Dividing by a number smaller than 1 makes the answer bigger: 10 ÷ 0.5 = 20, and 10 ÷ 0.9 = 11.1..., also bigger than 10. So the last claim, that dividing by 0.9 gives less than 10, is false.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- rnd-tick-significant-figures  (band 3, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'Significant figures start at the first non-zero digit, so the 4 in 0.045 is the first significant figure and the leading zeros only hold the place. 0.512 is much nearer 0.5 than 1, so it does not round up to 1. For 4,753 to 2 significant figures, round the 7 up to 8 in the hundreds, giving 4,800; 4,750 would be rounding to the nearest ten.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-tick-leading-zeros  (band 3, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'Leading zeros sit in front of the first non-zero digit and are only placeholders, so they are never significant. The significant figures of 0.045 are 4 and 5. Rounding 0.0045 to 1 significant figure gives 0.005, not 0.05: the first digit stays in the same column when you round.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-tick-trailing-zeros  (band 3, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'A zero after the decimal point and after the first non-zero digit is significant, because it records how precisely the number was measured. So 3.40 has three significant figures (3, 4 and 0) and 0.070 has two (7 and the final 0); the leading zero before the 7 does not count.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-nearest-hundred  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 3,486 to the nearest hundred.', 'The tens digit is 8, which is 5 or more, so the hundreds digit 4 rounds up to 5, giving 3,500. Cutting the number down to 3,400 ignores that. 3,490 is rounded to the nearest ten. Rounding all the way up to 4,000 goes one place too far.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-one-decimal-place  (band 1, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 2.41 to 1 decimal place.', 'The second decimal digit is 1, which is less than 5, so the tenths digit stays as it is: 2.4. Rounding up to 2.5 would need a 5 or more in the hundredths. 2.0 throws away the tenths as well, and 2.41 has not been rounded at all.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-halfway-045  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 0.45 to 1 significant figure.', 'The first significant figure is the 4 in the tenths column, and the next digit is 5, so it rounds up to give 0.5. Keeping 0.4 would be rounding down. 0.05 changes the column of the first significant figure. 1 would round each part of the number separately and lose the tenths entirely.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-estimate-product  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Estimate 39 × 21 by rounding each number to 1 significant figure.', '39 rounds to 40 and 21 rounds to 20, so the estimate is 40 × 20 = 800. 819 is the exact answer, found by calculating and not estimating at all. 600 would come from rounding 39 down to 30, which is not the nearest ten.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-tick-estimation  (band 3, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'An estimate rounds the numbers first and then works with the easier values, so 298 + 405 becomes 300 + 400 = 700 and 19 × 21 becomes 20 × 20 = 400. It is meant to be close to the exact answer, not equal to it, so it is not wrong merely for being approximate. Working out the exact answer first and rounding afterwards is not estimating. Adding 20 + 20 = 40 replaces the multiplication with an addition.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-tick-dp-vs-sf  (band 2, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'Decimal places are counted after the point; significant figures are counted from the first non-zero digit. So 2 decimal places gives 3.14, and 2 significant figures gives 3.1. Three significant figures gives 3.14 as well, because the 3, 1 and 4 are the first three significant figures. Rounding to 3 with 2 decimal places has kept the wrong number of places.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-tick-truncate  (band 2, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'Rounding looks at the next digit: 8 rounds 6.78 up to 6.8, and 9 rounds 0.499 up to 0.5 even though the digit before it is small. For 2.05 the next digit is 5, so the tenths digit goes up to give 2.1. Cutting the digits off without looking at the next one gives 6.7, 0.4 and 2.0.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-not-round-to-03  (band 4, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Which of these numbers does NOT round to 0.3 when rounded to 1 significant figure?', 'At 1 significant figure the first digit is the tenths digit. The digits 0.27, 0.34 and 0.25 all round to 0.3: 7 and 5 round the 2 up, and 4 leaves it. 0.35 rounds up to 0.4, because the hundredths digit is 5 and the tenths digit goes up from 3 to 4.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-27481-2sf  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Round 27,481 to 2 significant figures.', 'The first two significant figures are 2 and 7. The next digit is 4, which is less than 5, so the 7 stays and the rest become zeros: 27,000. 27,500 is rounded to the nearest hundred and 27,480 is cut off rather than rounded. 28,000 rounds the 7 up even though the next digit is only 4.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-estimate-quotient  (band 3, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Estimate 612 ÷ 28 by rounding each number to 1 significant figure.', '612 rounds to 600 and 28 rounds to 30, so the estimate is 600 ÷ 30 = 20. 21 is the exact answer rounded, which is calculating rather than estimating. 200 would come from rounding 28 to 3, which drops a digit.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-bridge-pencil-boxes  (band 2, single_choice)
values ((select id from topics where slug = 'rounding-and-estimation'), 'A school buys 19 boxes of pencils at £4.90 each. Which is the best estimate of the total cost?', 'Round both numbers to 1 significant figure: 19 becomes 20 and £4.90 becomes £5, so the estimate is 20 × £5 = £100. £95 rounds only the price and leaves 19 as it is. £93.10 is the exact total, not an estimate. £120 comes from rounding £4.90 up to £6, which is not the nearest pound.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- rnd-retention-whole-numbers  (band 1, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'To round to the nearest whole number, look at the first decimal digit: 7 rounds 4.7 up to 5, 3 leaves 12.3 as 12, and 8 rounds 12.8 up to 13. Cutting off the decimal part instead gives 4 and 12, which are not the nearest whole numbers. 4.7 does lie between 4 and 5, which is why one of them is the nearest.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- rnd-tick-part-round-2  (band 2, multi_select)
values ((select id from topics where slug = 'rounding-and-estimation'), 'Tick every statement that is true.', 'A digit of 5 rounds up, so 6.5 goes to 7 and 3.49 goes to 3.5 because the 9 rounds the 4 up. Rounding 0.512 to 1 significant figure keeps it in the same size of number — 0.5, not 1. Cutting off the second decimal digit of 3.49 gives 3.4, which is rounding down when the next digit is 9.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- frac-tick-add-compare  (band 2, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'Denominators must match before adding: 1/2 + 1/3 = 3/6 + 2/6 = 5/6. Adding the tops and the bottoms gives 2/5, which is smaller than either fraction. A fifth is a smaller piece than a third, even though 5 is a larger number. To divide by 1/3, multiply by 3/1 and get 2; flipping the other fraction gives 2/9.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-tick-compare-1  (band 2, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'For unit fractions the smaller denominator means the larger piece, so 1/2 > 1/3 and 1/4 > 1/5. With the same denominator, more parts is more, so 3/8 < 5/8. Comparing the parts separately, as in 2 > 1 for 2/5 and 1/2, gets 2/5 wrong: 2/5 = 0.4 is less than 0.5. 2/3 = 0.667 is less than 3/4 = 0.75. 4/6 reduces to 2/3 by dividing both parts by 2.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-add-quarters  (band 1, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 1/4 + 1/4?', 'The denominators are already the same, so add the numerators: 1/4 + 1/4 = 2/4, which simplifies to 1/2. Adding the bottoms as well gives 2/8, which happens to be 1/4 — the size of one part, not two. Adding only the bottoms gives 1/8. Multiplying the bottoms to 16 gives 2/16.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-tick-subtract  (band 3, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'For 3/4 − 1/4 the denominators match, so subtract the tops: 2/4 = 1/2. For 5/6 − 1/6, subtract to get 4/6 = 2/3. For 1/2 − 1/3, first write both as sixths: 3/6 − 2/6 = 1/6. Subtracting the bottoms as well gives 0/1, or 0, which is not 1/6.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-smallest-unit-fraction  (band 1, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which of these fractions is the smallest?', 'The more pieces a whole is cut into, the smaller each piece is, so 1/10 is the smallest. Choosing 1/2 because 2 is the smallest number reads the denominator as the size of the piece instead of as the number of pieces.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-tick-equivalence  (band 2, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'Equivalent fractions come from multiplying the top and the bottom by the same number: 2/3 = 4/6 and 8/12 = 2/3 (both parts of 8/12 divided by 4). Adding the same number to the top and the bottom, as in 2/3 to 3/4, changes the value. In 2/3 = 4/9 the top has been multiplied by 2 and the bottom by 3, so the two fractions are not equal. 5/10 = 1/2 by dividing both parts by 5.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-tick-simplify  (band 3, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'Simplifying divides the top and the bottom by a common factor: 4/6 = 2/3 divides by 2, 8/12 = 4/6 also divides by 2, and 9/12 = 3/4 divides by 3. Taking 1 off each part, 4/6 to 3/5, is subtracting rather than dividing. 10/15 = 2/3 when both parts are divided by 5, not 2/5. A fraction whose top and bottom are equal is one whole, so 5/5 = 1.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-equivalent-to-3-4  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which fraction is equivalent to 3/4?', 'Multiply the top and the bottom by the same number: 3/4 = 6/8. 4/5 and 6/7 come from adding 1 or 3 to each part, which changes the value. In 9/16 the top is multiplied by 3 but the bottom by 4, so the fractions are not equal.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-three-quarters-of-20  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 3/4 of 20?', 'First find 1/4 by dividing 20 by 4, which is 5, then take three of them: 3 × 5 = 15. Stopping after the division gives only 1/4 of 20. Multiplying by the numerator without dividing gives 60. Dividing by 3/4 instead of multiplying gives about 26.67.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-tick-of-amount  (band 2, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'Divide by the denominator, then multiply by the numerator: 2/5 of 30 is 30 ÷ 5 = 6, then 6 × 2 = 12; 5/6 of 24 is 24 ÷ 6 = 4, then 4 × 5 = 20; 1/4 of 100 is 25. Doing only the division gives 4 for 2/3 of 12 and 9 for 1/3 of 18, which is one part rather than the fraction asked for. 15 is 3/4 of 20, not 3/5 of 20.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-reverse-three-fifths  (band 4, single_choice)
values ((select id from topics where slug = 'fractions'), '3/5 of a number is 12. What is the number?', '12 is three fifths, so one fifth is 12 ÷ 3 = 4, and the whole is 5 × 4 = 20. Taking 3/5 of 12 keeps applying the fraction and gives 7.2. Multiplying 12 by 3 gives 36, which uses the numerator in the wrong direction; the whole is smaller than that. Adding 3 gives 15, which treats the fraction as a label rather than an operation.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-divide-two-thirds  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 2/3 ÷ 1/3?', 'To divide by 1/3, multiply by its reciprocal 3/1: 2/3 × 3/1 = 6/3 = 2. It also makes sense as a question — how many thirds are in two thirds? Two. Multiplying the fractions instead gives 2/9. Flipping the first fraction gives 3/2 × 1/3 = 1/2, and flipping both gives 9/2.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-multiply-half-third  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'What is 1/2 × 1/3?', 'To multiply fractions, multiply the numerators and multiply the denominators: 1 × 1 over 2 × 3 gives 1/6. Putting both over a common denominator of 6 and then adding gives 5/6, which is 1/2 + 1/3, not the product. Adding across gives 2/5.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-tick-multiply-divide  (band 4, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'For multiplication, multiply across and simplify: 2/3 × 3/4 = 6/12 = 1/2 and 4/5 × 5/8 = 20/40 = 1/2. Adding across on the first gives 6/7. For division, multiply by the reciprocal: 3/5 ÷ 1/5 = 3/5 × 5/1 = 3, and 4/5 ÷ 5/8 = 4/5 × 8/5 = 32/25. Multiplying instead of inverting gives 1/2 for the last one.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-mixed-to-improper  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Write 2 3/4 as an improper fraction.', 'Two wholes are 8 quarters, plus the 3 quarters already there, makes 11 quarters. Adding the whole and the numerator, 2 + 3 = 5, forgets that each whole is four quarters. Multiplying 2 × 3 = 6 multiplies the whole by the numerator instead. Writing 23/4 just puts the digits together.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-improper-to-mixed  (band 3, single_choice)
values ((select id from topics where slug = 'fractions'), 'Write 11/4 as a mixed number.', 'Each whole is 4 quarters, so 11 ÷ 4 is 2 wholes with 3 quarters left over: 2 3/4. A remainder of 1 gives the wrong fractional part, and 3 wholes would be 12 quarters, which is more than 11. Any improper fraction, where the numerator is larger, can be written as a mixed number.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-bar-as-decimal  (band 2, single_choice)
values ((select id from topics where slug = 'fractions'), 'Which number is equal to 5/3?', '5/3 means 5 ÷ 3, which is 1 with 2 left over, so it is 1 2/3. The fraction bar is a division sign, not a decimal point, so it does not make 5.3. Reading the numbers as 5 × 3 gives 15.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-bridge-recipe-sugar  (band 4, single_choice)
values ((select id from topics where slug = 'fractions'), 'A recipe uses 3/4 cup of sugar. Zak makes half the recipe. How much sugar does he use?', 'Half of 3/4 is 3/4 × 1/2 = 3/8. Leaving it at 3/4 forgets the halving altogether. 1/4 would come from looking at the denominator only. 1 1/2 cups is doubling, not halving.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- frac-retention-equivalence  (band 2, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'Multiply or divide the top and the bottom by the same number: 1/2 = 2/4, 1/3 = 2/6, 2/8 = 1/4 (divide both by 2) and 1/5 = 2/10. Adding 1 to each part of 3/4 gives 4/5, which is a different value. Multiplying 2/3 by 2 on top and 3 on the bottom gives 4/9, where the two parts have been scaled differently.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- frac-tick-whole-numbers  (band 1, multi_select)
values ((select id from topics where slug = 'fractions'), 'Tick every statement that is true.', 'A fraction with the same numerator and denominator is one whole: 7/7 = 1 and 4/4 = 1, not 0 or 4. A fraction over 1 just means the whole number of parts: 5/1 = 5. But 1/5 is a fifth of one, not 5 — the top and bottom cannot simply be swapped.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-tick-percent-basics  (band 3, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'Per cent means per hundred, so 25% is a quarter and a quarter of 240 is 60; it is not the number 25. A 15% increase adds 12 to 80 (10% is 8 and 5% is 4), giving 92, not 95. 0.6 = 6/10 = 3/5; 1/6 is about 0.167.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-percent-of-240  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'What is 25% of 240?', '25% is one quarter, and 240 ÷ 4 = 60. Giving 25 as the answer treats the percentage as the amount itself. Leaving the answer as 240 leaves the amount unchanged. 48 would be 20% of 240.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-tick-percent-as-number  (band 2, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'A percentage is a fraction of the amount, not a fixed number. 10% of 50 is 5, not 10; 50% of 80 is 40, not 50; and 100% of 37 is the whole of 37, which is 37, not 100.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-increase-80-by-15  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Increase 80 by 15%.', '15% of 80 is 12, so the increase is 80 + 12 = 92. Adding 15 to 80 treats the percentage as 15 units and gives 95. Subtracting instead of adding gives 68. Stopping at 12 gives the increase on its own, not the new amount.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-tick-increase-decrease  (band 3, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'Find the percentage of the amount first: 10% of 80 is 8, so 80 + 8 = 88, not 90. 25% of 60 is 15, so 60 − 15 = 45; subtracting 25 itself gives 35. 50% of 200 is 100, so 200 + 100 = 300, not 250.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-increase-multiplier  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which multiplier increases an amount by 15%?', 'Adding 15% to the whole leaves 115% of the original, which is the multiplier 1.15. Multiplying by 0.15 finds only the increase itself. 0.85 is the multiplier for a 15% decrease. 15 treats the percentage as a whole number.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-percentage-points  (band 3, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A pass rate rises from 20% to 25%. By how many percentage points does it rise?', 'Percentage points are found by subtracting: 25 − 20 = 5, so the rise is 5 percentage points. The rise is 25% of the original 20, which is a different fact from the number of percentage points. Quoting 20 or 25 confuses the two rates with the change between them, and 1.25 compares one rate with the other rather than subtracting.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-tick-percentage-points  (band 4, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'Percentage points are the simple difference between two rates: 25 − 20 = 5 and 50 − 40 = 10. The relative change is the difference divided by the original: for 40% to 50% that is 10 ÷ 40 = 0.25, a 25% increase. Calling a 5-point rise ''a rise of 25%'' or a 10-point rise ''a rise of 10%'' mixes the two measures up.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-reverse-discount  (band 4, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'In a sale a coat is reduced by 25% and now costs £45. What was the original price?', '£45 is 75% of the original price, so 1% is £45 ÷ 75 = £0.60 and 100% is £60. Adding 25% of £45 back on gives £56.25, which overshoots because the 25% was taken from the original, larger amount. Taking another 25% off gives £33.75, going the wrong way. £70 cannot be right because 75% of £70 is £52.50, not £45.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-reverse-increase  (band 4, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A price is increased by 20% and is now £72. What was the price before the increase?', '£72 is 120% of the old price, so 1% is £72 ÷ 120 = £0.60 and 100% is £60. Subtracting 20% of £72 gives £57.60, which is too small because the 20% was of the smaller original. Adding 20% again gives £86.40. £52 does not satisfy the original statement either: 20% of £52 is £10.40, giving £62.40.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-tick-reverse-percentages  (band 4, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'To undo a percentage change, divide by the multiplier. £55 after a 10% rise means the original was £55 ÷ 1.1 = £50; subtracting 10% of £55 gives £49.50, which is too small. £80 after a 20% fall means the original was £80 ÷ 0.8 = £100; adding 20% of £80 gives £96, also too small. A 50% rise makes the price 1.5 times the original, so halving the new price gives 0.75 of the original, not the original.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-fraction-to-percent  (band 1, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which percentage is equal to 2/5?', '2/5 = 4/10 = 0.4 = 40%. 20% is 1/5, which uses only the denominator and has lost the numerator. Reading 2/5 as the decimal 2.5 comes from treating the bar as a decimal point. 2.5 as a percentage would be 250%, which is more than the whole.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-decimal-to-percent  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Which percentage is equal to 0.4?', 'To turn a decimal into a percentage, multiply by 100: 0.4 = 40%. 0.4 is four tenths, which is 40 hundredths, so 4% is ten times too small. Multiplying by 1000 gives 400%, and leaving the decimal unchanged gives 0.4%.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-percent-to-decimal  (band 1, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Write 7% as a decimal.', '7% means 7 per hundred, which is 7 ÷ 100 = 0.07. 0.7 would be 70%, and 0.007 would be 0.7%. Keeping the 7 treats the percentage as the number itself.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-tick-conversions  (band 3, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', '3/4 = 0.75 = 75%, 0.25 = 1/4 and 2/5 = 0.4 = 40%. 0.6 is 60%, not 6%, and 0.09 is 9%, not 90%. One third is 0.333... with the 3s carrying on for ever, so it cannot be written exactly as 0.3.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-tick-compare-order  (band 2, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'Write everything as decimals to compare: 1/3 = 0.333..., which is less than 0.35. 35% is 0.35, so it is greater than 0.3. 2/5 is exactly 0.4, so 0.4 is not less than 2/5 — they are equal.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fdp-bridge-double-discount  (band 2, single_choice)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'A shop takes 20% off a £45 jacket. It then takes a further 10% off the sale price. What does the jacket cost now?', 'Take the discounts one at a time. 20% off £45 leaves £36; 10% off £36 takes off £3.60 and leaves £32.40. Adding the two discounts to 30% and taking that off £45 gives £31.50, which is too much off because the second discount applies to the smaller sale price. Stopping at £36 applies only the first discount.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fdp-retention-fraction-decimal  (band 1, multi_select)
values ((select id from topics where slug = 'fractions-decimals-percentages'), 'Tick every statement that is true.', 'Halves, quarters, tenths and fifths all give exact decimals: 1/2 = 0.5, 1/4 = 0.25, 1/10 = 0.1 and 1/5 = 0.2. 3/4 is 0.75, not 0.34 — the 34 comes from reading the bar as a decimal point. One third is 0.333... repeating, so 0.3 is only an approximation.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-tick-counters-4-3  (band 3, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Red and blue counters are in the ratio 4:3. There are 20 red counters. Tick every statement that is true.', '20 red means the ratio was scaled up 5 times, so the blue count is 3 × 5 = 15 and the total is 20 + 15 = 35. Taking 1 off 20 to get 19, or adding 4 and 3 to get 19, treats the ratio as a difference. The ratio compares red to blue, so the whole is 7 parts, and blue is 3/7 of the counters, not 3/4.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-tick-simplify  (band 1, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Tick every statement that is true.', 'A ratio is simplified by dividing both parts by the same number: 4:6 and 6:9 divide by 3, and 10:15 divides by 5, all giving 2:3. Taking 1 off each part, as in 4:6 to 3:5, changes the relationship instead of keeping it the same.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-red-fraction  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'The ratio of red to blue counters in a box is 2:5. What fraction of the counters are red?', 'The ratio 2:5 makes 7 parts altogether, 2 of them red, so red is 2/7 of the counters. 2/5 compares red with blue only, which is a part-to-part comparison. 5/7 is the fraction that is blue, and 5/2 puts the parts the wrong way round and is greater than one.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-tick-class-3-4  (band 3, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'In a class the ratio of boys to girls is 3:4. Tick every statement that is true.', 'The ratio 3:4 gives 7 parts in total, so boys are 3/7 of the class and girls are 4/7. Writing 3/4 compares one group with the other rather than with the whole class. Since there are more girls than boys, the number of girls is 4/3 of the number of boys, not 3/4.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-recipe-rice  (band 1, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'A recipe for 4 people uses 300 g of rice. How much rice is needed for 10 people?', 'Find the amount for one person first: 300 ÷ 4 = 75 g, then multiply by 10 to get 750 g. 600 g is only enough for 8 people. 375 g is 5 people''s worth. 900 g is three times 300, which serves 12 people.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-tick-proportion  (band 2, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Tick every statement that is true.', 'When quantities are in direct proportion, doubling one doubles the other: twice the pens cost twice as much, and three times the flour costs three times as much. Adding £1.50 and £3.00 is not the point — £4.50 would price 9 pens. For workers and time the relationship is the other way round: more workers means less time, so 4 workers take 3 hours, not 12.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-inverse-workers  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Six workers take 4 days to build a wall. How long would twelve workers take, working at the same rate?', 'Twice as many workers do the job in half the time, so 12 workers take 2 days. Doubling the time to 8 days treats this as direct proportion. Leaving it at 4 days ignores the extra workers, and 72 days multiplies the workers by the days instead of dividing.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-tick-inverse  (band 4, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Tick every statement that is true.', 'For a fixed job, workers and time are inversely proportional: halving the workers doubles the time (2 people take 18 hours), and doubling the machines halves the time (6 taps take 10 minutes). Treating these as direct proportion gives 4.5 hours and 40 minutes. More workers means less time, provided everyone works at the same rate.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-share-sweets  (band 1, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Sweets are shared between two children in the ratio 3:2. There are 30 sweets. How many does the child with the larger share get?', 'The ratio 3:2 has 5 parts, so each part is 30 ÷ 5 = 6 sweets. The larger share is 3 parts, which is 18. 12 is the smaller share, so that swaps the children over. 20 comes from dividing 30 by 3 rather than by 5, and 15 splits the sweets evenly.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-simplify-units  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Simplify the ratio 40 minutes : 2 hours.', 'Both parts must be in the same unit. 2 hours is 120 minutes, and 40:120 divides by 40 to give 1:3. Dividing 40 by 2 without converting gives 20:1, which compares different units. Reading 40 minutes as 0.4 of the second part, or as one hour, gives 1:2 or 2:1.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-whole-to-part  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'In a bag, 3/5 of the counters are red. The rest are blue. What is the ratio of red to blue counters?', 'If 3/5 are red then 2/5 are blue, so red to blue is 3:2. The ratio 3:5 is red to the whole bag, not red to blue. 5:3 puts the whole before the blue part, and 2:3 reverses the order.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-three-part-share  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), '£240 is shared in the ratio 2:3:5. What is the largest share?', 'The ratio has 2 + 3 + 5 = 10 parts, so each part is £240 ÷ 10 = £24. The largest share is 5 parts, which is £120. £48 and £72 are the two smaller shares. £100 would come from dividing by 12 instead of 10, which is not the number of parts.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-tick-three-part  (band 4, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Tick every statement that is true.', 'The parts of 1:2:3 add to 6, so each part of £60 is £10 and the shares are £10, £20 and £30. The largest share is 3 out of 6 parts, which is 1/2 of the total, not 3/5. £15, £30 and £45 would need 8 parts. Multiplying every part by the same number keeps a ratio the same, so 1:2:3 = 2:4:6; changing only the last part does not.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- ratio-adults-children  (band 2, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'At a show the ratio of adults to children is 5:3. There are 40 adults. How many children are there?', '40 adults is 5 parts, so each part is 8 people, and children are 3 parts: 3 × 8 = 24. Stopping at 8 gives only one part. 15 is 5 × 3, which multiplies the two parts of the ratio together. 64 adds the adults to the children''s share without working out the parts.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-bridge-paint  (band 3, single_choice)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Paint is mixed from red and white in the ratio 2:5. Tom uses 600 ml of white paint. How much red paint does he need?', '600 ml is 5 parts, so each part is 120 ml, and red is 2 parts: 2 × 120 = 240 ml. 1200 ml doubles the white instead of finding the red, and 300 ml halves the white rather than using the ratio. 840 ml adds the two figures instead of scaling them.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- ratio-retention-fractions  (band 1, multi_select)
values ((select id from topics where slug = 'ratio-and-proportion'), 'Tick every statement that is true.', 'Divide by the denominator and multiply by the numerator: 1/2 of 40 is 20, 1/4 of 40 is 10, 3/4 of 40 is 30 and 1/5 of 45 is 9. 2/3 of 9 is 6, not 3 — 3 is only one third. 3/5 of 20 is 12, not 15: 20 ÷ 5 = 4 and 4 × 3 = 12.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-tick-equal-5a  (band 2, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every expression that is equal to 5a.', 'a is a number, so 3a + 2a is five of them, a × 5 is five of them, and 10a ÷ 2 is five of them. 5 + a cannot be collected because 5 and a are not like terms. 5a² is five lots of a², which is a different size. a + a + a + a is only 4a.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-tick-unlike-terms  (band 2, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every statement that is true.', 'Only like terms can be collected. 3x and 2x are both x terms, so they add to 5x, and 4a − a = 3a. But 2a and 3b are different letters, so they stay separate; writing 5ab multiplies the letters together instead of adding them. 4a + 3 has a number term and an a term, and they cannot be combined into 7a.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-multiply-2a-3a  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify 2a × 3a.', '2a × 3a is 2 × 3 × a × a, so multiply the numbers to get 6 and the letters to get a²: 6a². Writing 6a keeps only one a. 5a² and 5a add the coefficients instead of multiplying them.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-tick-squares  (band 2, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every statement that is true.', 'Adding two a''s gives 2a; multiplying a by a gives a². They are the same only when a happens to be 2, so a² = 2a is not true in general. a × a × a is a³, not 3a.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-substitute-3a  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of 3a when a = −2.', '3a means 3 × a, so 3 × (−2) = −6. Dropping the minus sign gives 6. Adding instead of multiplying gives 3 + (−2) = 1, and writing −1 takes the wrong sign from that addition.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-substitute-square  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of a² when a = −3.', 'a² means a × a, so (−3) × (−3) = 9. A negative multiplied by a negative is positive, so −9 is wrong. −6 comes from treating a² as 2a, which gives 2 × (−3) = −6. 6 keeps the size but loses the minus sign from the multiplication.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-tick-substitution  (band 3, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'When x = 4, tick every statement that is true.', 'Substituting x = 4: 2x is 2 × 4 = 8; x² is 4 × 4 = 16; x + 3 = 7; and 4 − 6 = −2. x² = 8 would be doubling rather than squaring. 5 − x is 5 − 4 = 1, not 9: 9 comes from adding 5 and 4, or from working out 4 − 5 with the sign forgotten.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-five-more-than-n  (band 1, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which expression means "5 more than n"?', 'Five more than n means add 5 to n, which is n + 5. 5n means 5 times n. n − 5 and 5 − n subtract instead of adding, and both depend on which way round the subtraction is written.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-divided-by-2  (band 2, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which expression means "a divided by 2"?', '"a divided by 2" puts the a on top: a/2. Writing 2/a divides 2 by a, which is a different expression and is not even defined when a = 0. 2a means 2 times a, and a − 2 subtracts rather than divides.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-3a-as-sum  (band 2, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Which of these is equal to 3a?', '3a means 3 lots of a, so it is a + a + a. a × a × a is a³, which is a different expression. 3 + a and a + 3 both add the number 3 to a single a instead of repeating the a three times.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-error-collecting  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Jaz writes 2a + 3b = 5ab. What has she done?', '2a and 3b are not like terms, so they cannot be collected: the expression is already simplified as 2a + 3b. Adding the numbers but also multiplying the letters gives 5ab. Keeping the letters separate would give 5a + 5b, which is also wrong. Making both letters 1 would give 2 + 3 = 5, with no letters at all.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-tick-mult-not-add  (band 2, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every statement that is true.', 'Adding like terms adds the coefficients: 3a + 2a = 5a and 2a + 2a = 4a. Multiplying multiplies both the numbers and the letters: 2a × 2a = 4a², and a × a = a². Treating an addition as a multiplication gives 6a²; treating a multiplication as an addition gives 4a.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-simplify-5x-3y  (band 1, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify 5x + 3y.', 'x and y are different letters, so 5x and 3y are not like terms and cannot be combined; the expression is already as simple as it gets. 8xy adds the coefficients but also multiplies the letters. 8x + y adds only one of the coefficients to the wrong term. 15xy multiplies the terms instead of adding them.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-simplify-a-plus-a-squared  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Simplify a + a².', 'a and a² are not like terms: one is a single a and the other is a multiplied by itself, so the expression cannot be simplified. Adding to get 2a² treats them as the same. a³ would come from multiplying a by a². 2a treats a² as another a.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-bridge-perimeter  (band 3, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'A rectangle is a cm long and 3 cm wide. Which expression gives its perimeter?', 'The perimeter is 2(a + 3), which expands to 2a + 6. a + 3 is the length plus the width, which is only half the perimeter. 2a + 3 doubles the length but not the width. 3a multiplies the two side lengths, which gives the area, not the perimeter.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- alg-retention-substitution  (band 1, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every statement that is true.', 'A letter stands for a number, so replace it and work out the arithmetic: a + 2 = 9, 3b = 15, c ÷ 2 = 5 and e − 2 = 4. d² is d × d = 16, not 2 × d = 8. 2f is 2 × 3 = 6, not 2 + 3 = 5.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-tick-letter-as-object  (band 1, multi_select)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Tick every statement that is true.', 'A letter is a number, not an object, so it can only be collected with like terms. 4 + a is a number plus an unknown and stays as it is; it does not become 4a. The same goes for 5 + a and 3 + x. x + x + x is three lots of the same term, so it is 3x. Plain arithmetic like 2 + 2 = 4 is unchanged.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- alg-substitute-two-terms  (band 4, single_choice)
values ((select id from topics where slug = 'expressions-and-simplifying'), 'Work out the value of 2a + 3b when a = 5 and b = −2.', 'Substitute both values: 2 × 5 + 3 × (−2) = 10 + (−6) = 4. Treating 3 × (−2) as +6 gives 16. Getting the sign the wrong way round entirely gives −4. 10 ignores the b term and works out only 2a.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-tick-expand-factorise  (band 3, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', 'The multiplier outside a bracket applies to every term inside it, so 3(x + 4) = 3x + 12. A minus sign in front of a bracket changes the sign of every term, so −(x + 3) = −x − 3. When factorising, the highest common factor must be taken out of both terms: 3 divides both 6x and 9, giving 3(2x + 3). Taking it from only the first term leaves 3(2x + 9), which expands back to 3x + 9.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- exp-expand-4x-plus-5  (band 2, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand 4(x + 5).', 'Multiply both terms inside the bracket by 4: 4 × x = 4x and 4 × 5 = 20, so the answer is 4x + 20. Leaving the 5 alone gives 4x + 5, and adding 4 and 5 gives 4x + 9. Dropping the 4 from the x term gives x + 20.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-minus-bracket-single  (band 2, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand −(x + 4).', 'The minus sign in front of the bracket applies to both terms: −x − 4. Applying it only to the x gives −x + 4. Dropping the minus altogether gives x + 4, and moving it to the wrong term gives x − 4.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-tick-minus-brackets  (band 3, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', 'Multiply every term by −2: −2 × x = −2x and −2 × (−3) = +6, so −2(x − 3) = −2x + 6. In the same way −(a + b) = −a − b. For 5 − (x + 2), the bracket is subtracted, so both signs inside change: 5 − x − 2 = 3 − x. Leaving the term unchanged, as in −2x − 6 or 7 − x, applies the sign to only one term.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fac-fully-6x-plus-9  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Factorise fully 6x + 9.', '3 is the highest common factor of 6x and 9, so 6x + 9 = 3(2x + 3). Taking the 3 out of only the first term gives 3(2x + 9). Using 9 as the factor gives 9x + 9, which is not the original. Using 6, the coefficient of the first term only, gives 6x + 18.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- exp-tick-factorise-single  (band 3, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', 'Take the common factor out of both terms: 4 from 4x and 8, 5 from 5x and 10, and x from x² and 3x. Writing 4(x + 8) leaves the 8 untouched; 5(x + 10) leaves the 10 untouched; and x(x + 3x) leaves the x in the second term.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- fac-2x-plus-4  (band 1, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Factorise 2x + 4.', '2 divides both 2x and 4, so 2x + 4 = 2(x + 2). Writing 2(x + 4) expands back to 2x + 8, and 2(x + 1) expands to 2x + 2. Taking x out is wrong because the 4 has no x in it, and x(2 + 4) expands to 6x.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fac-quadratic-7-12  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Factorise x² + 7x + 12.', 'The two numbers must multiply to 12 and add to 7: 3 × 4 = 12 and 3 + 4 = 7. Using the 7 and 12 from the expression gives (x + 7)(x + 12), which multiplies to x² + 19x + 12. 1 × 12 = 12 but 1 + 12 = 13. 2 × 6 = 12 but 2 + 6 = 8.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
delete from seed_question;
-- fac-tick-sum-product  (band 4, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', 'To factorise x² + bx + c, find two numbers that multiply to c and add to b. For x² + 7x + 12 they are 3 and 4; for x² + 7x + 10 they are 2 and 5; for x² + 5x + 6 they are 2 and 3. Using the coefficients 7 and 12, or 5 and 6, directly gives brackets that multiply out to the wrong middle term.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
