-- exp-double-bracket  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand (x + 2)(x + 3).', 'Multiply every term in the first bracket by every term in the second: x × x = x², x × 3 = 3x, 2 × x = 2x and 2 × 3 = 6, giving x² + 5x + 6. Multiplying only the first terms gives x² + 6. Adding the constants wrongly gives 5, and adding the x terms wrongly gives 6x.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
