-- exp-square-bracket  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand (x + 3)².', '(x + 3)² means (x + 3)(x + 3), which expands to x² + 3x + 3x + 9 = x² + 6x + 9. Squaring each term separately gives x² + 9 and loses the two middle terms. Using only one 3x loses the other, and squaring the 3 to 6 is an arithmetic slip.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
