-- exp-collect-3x-plus-2  (band 3, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Expand and simplify 3(x + 2) + 2x.', 'Expand first: 3x + 6 + 2x. Then collect the like terms 3x and 2x to get 5x + 6. Stopping before collecting leaves 3x + 6 + 2x. Adding only the 2 to the bracket gives 5x + 2, and treating 3 + 2 + 2 as 7 gives 7x + 6.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
