-- exp-tick-collect  (band 4, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', 'Expand and then collect: 2x + 6 + 4x = 6x + 6; 5x + 5 − x = 4x + 5; and 4x + 8 − 3x = x + 8. Each false option is the expanded form with the x terms still uncollected, so the expression is not wrong but it is not simplified.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
delete from seed_question;
-- exp-bridge-rectangle-area  (band 4, single_choice)
values ((select id from topics where slug = 'expanding-and-factorising'), 'A rectangle is (x + 5) cm long and 3 cm wide. Which expression gives its area in cm²?', 'Area is length × width, so 3(x + 5) = 3x + 15. Multiplying only the x by 3 gives 3x + 5. Adding 3 and 5 instead of multiplying gives 3x + 8. Dropping the 3 from the x term gives x + 15.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 7);
