-- exp-retention-collecting  (band 1, multi_select)
values ((select id from topics where slug = 'expanding-and-factorising'), 'Tick every statement that is true.', '2x and 3x are like terms and add to 5x; 4a − a = 3a; and x + x = 2x. 2x and 3y are different terms and cannot be combined, so 5xy is wrong. 3 and 2x are a number and a letter term, so they stay separate; 5x − 5 is likewise as simple as it gets.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 7);
