-- eq-error-4x-minus-5  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Sam solves 4x − 5 = 27 and gets x = 5.5. Which mistake did Sam make?', '4x − 5 = 27 becomes 4x = 32 by adding 5 to both sides, so x = 8. Sam did 27 − 5 = 22 and then divided by 4, which gives 5.5. To undo ''subtract 5'' you must add 5. Dividing by 5, forgetting to divide, or multiplying by 4 would all give different wrong answers.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-solve-2x-plus-5  (band 1, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 2x + 5 = 13.', 'Subtract 5 from both sides to get 2x = 8, then divide by 2 to get x = 4. Adding 5 instead gives 2x = 18 and x = 9. Dividing by 2 first gives 6.5. Subtracting but stopping before dividing gives 8.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-tick-one-step  (band 3, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', 'Undo each operation by doing the opposite to both sides. 2x + 5 = 13 gives 2x = 8 and x = 4; adding 5 gives x = 9. 3x = 12 gives x = 4, and 5x = 45 gives x = 9. x − 7 = 3 gives x = 10 by adding 7; writing −4 subtracts 7 again instead.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-error-order-inverse  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Lina solves 3x + 2 = 11 by working out (11 + 2) ÷ 3 = 4.33. What has she done?', '3x + 2 = 11 becomes 3x = 9 by subtracting 2, so x = 3. Lina has added 2, giving 13 ÷ 3 = 4.33. Dividing by 3 first would give 11/3 − 2; multiplying by 3 or stopping at 3x = 9 would give different results again.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-both-sides-5x  (band 2, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 5x = 2x + 9.', 'Subtract 2x from both sides to get 3x = 9, so x = 3. Adding the x terms, 5x + 2x = 7x, gives the equation 7x = 9 and the wrong answer 9/7. Ignoring the 2x leaves 5x = 9, so x = 1.8.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-tick-both-sides  (band 3, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', 'Collect the x terms on one side by subtracting the smaller amount: 4x = x + 9 gives 3x = 9 and x = 3; 6x = 2x + 8 gives 4x = 8 and x = 2; 3x + 4 = x + 10 gives 2x = 6 and x = 3. Adding the x terms instead of subtracting, or combining the numbers and letters carelessly, gives 9/5, 1 and 7.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-negative-solution  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve x + 5 = 2.', 'Subtract 5 from both sides: x = 2 − 5 = −3. Adding 5 gives 7. Writing 3 keeps the size but drops the sign, and saying there is no solution assumes an answer cannot be negative. A negative value is perfectly possible.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-tick-negative-solutions  (band 4, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', 'x + 5 = 2 gives x = −3, 2x = −8 gives x = −4, and x − 3 = −7 gives x = −4 by adding 3. None of these equations is impossible; the solutions are simply negative. Insisting that a solution must be positive rejects all three correct answers.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-fraction-coefficient  (band 2, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve x/3 = 4.', 'x is divided by 3, so multiply both sides by 3: x = 12. Dividing 4 by 3 gives 4/3, which does the wrong operation. Adding 3 instead of multiplying gives 7, and taking the reciprocal of 12 gives 1/12.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-error-divide-all  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'To solve (x + 4)/2 = 5, Priya writes x + 4 = 5/2. What has she done?', 'The whole of x + 4 is divided by 2, so multiply both sides by 2 to get x + 4 = 10 and x = 6. Priya has divided 5 by 2 instead, which is the opposite of the operation needed. Subtracting before multiplying, multiplying only the x, or dropping the 4 would all give other wrong answers.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-bracket-solve  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 3(x − 2) = 9.', 'Divide both sides by 3 to get x − 2 = 3, then add 2 to get x = 5. Dividing 9 by 3 and then subtracting 2 instead of adding gives 1. Leaving the bracket alone and answering 9 ignores the 3, and 11/3 comes from dividing before undoing the subtraction in the wrong order.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-tick-one-side-and-fraction  (band 2, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', '4x − 5 = 27 gives 4x = 32 and x = 8; subtracting the 5 gives 5.5. 2x + 7 = 1 gives 2x = −6 and x = −3; adding 7 gives 4. x/4 = 3 gives x = 12 by multiplying by 4; dividing 3 by 4 gives 0.75.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-tick-balance-meaning  (band 3, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', 'An equals sign says the two sides are the same value; it is not an instruction to calculate. To keep that equality you must do the same thing to both sides. Adding to one side while subtracting from the other, or dividing only one side, breaks the balance and changes the solution.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-tick-one-side  (band 1, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', '3x = 15 gives x = 5, x + 2 = 7 gives x = 5 by subtracting 2, and 2x = 8 gives x = 4. In the false statements an operation has been applied to one side only: 4x + 3 no longer equals 12, and x = 9 adds 2 to the right-hand side instead of subtracting it.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-bridge-think-of-a-number  (band 3, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'I think of a number, multiply it by 4, then subtract 3. The result is 25. What was the number?', 'The equation is 4x − 3 = 25. Add 3 to get 4x = 28, then divide by 4 to get x = 7. Subtracting 3 instead gives 22 ÷ 4 = 5.5. Dividing by 4 before adding 3 gives 6.25 + 3 = 9.25. Adding 3 and stopping gives 28.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- eq-retention-substitution-check  (band 1, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', 'Substituting means replacing the letter with its value: 2 × 4 + 1 = 9, 3 + 5 = 8, and 3 × 2 = 6. 2x + 1 = 12 adds instead of multiplying. Writing 35 puts the digits together as if the letter were not a number. 3x = 5 adds 3 and 2 rather than multiplying.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-tick-two-step-fraction  (band 1, multi_select)
values ((select id from topics where slug = 'solving-equations'), 'Tick every statement that is true.', '5x = 45 gives x = 9, and x/5 = 9 gives x = 45 by multiplying by 5; dividing 9 by 5 gives 1.8. 2x + 3 = 11 gives 2x = 8 and x = 4. Adding 3 instead of subtracting gives (11 + 3) ÷ 2 = 7, and dividing by 2 before subtracting gives 11 ÷ 2 = 5.5.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- eq-negative-both-sides  (band 4, single_choice)
values ((select id from topics where slug = 'solving-equations'), 'Solve 3x − 4 = x + 2.', 'Subtract x from both sides to get 2x − 4 = 2, then add 4 to get 2x = 6 and x = 3. Answering 6 is the value of 2x, not x. Adding the x terms instead of subtracting gives 4x = 6 and x = 1.5. Getting both signs wrong in the rearrangement gives −3.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tick-arithmetic-4-7  (band 3, multi_select)
values ((select id from topics where slug = 'sequences'), 'For the sequence 4, 7, 10, 13, … tick every statement that is true.', 'The terms go up by 3, so the nth term starts 3n; at n = 1 that gives 3, so add 1 to get 3n + 1. Using the term-to-term rule as the formula gives n + 3, which gives 4, 5, 6 rather than 4, 7, 10. The 10th term is 3 × 10 + 1 = 31; 34 comes from adding 3 ten times to 4 instead of starting at n = 1. 67 = 3n + 1 gives n = 22, so 67 is in the sequence.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-nth-term-5-9  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'What is the nth term of the sequence 5, 9, 13, 17, …?', 'The terms increase by 4, so the formula starts 4n. At n = 1 that gives 4, but the first term is 5, so add 1: 4n + 1. Writing 4n gives 4, 8, 12. n + 4 gives 5, 6, 7, which follows the first term only. 4n + 5 gives 9, 13, 17 and misses the first term.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-nth-term-2-5  (band 1, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence starts 2, 5, 8, 11, … and increases by 3 each time. Which is the nth term?', 'The common difference is 3, so the formula is 3n plus or minus a number. At n = 1, 3n = 3 and the first term is 2, so subtract 1: 3n − 1. n + 3 gives 4, 5, 6, which is the rule rather than the formula. 3n and 3n + 2 miss the first term by one step in each direction.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tick-geometric  (band 3, multi_select)
values ((select id from topics where slug = 'sequences'), 'Tick every statement that is true.', 'A sequence that doubles is not the times table: 5, 10, 20, 40 gives 5 × 2ⁿ⁻¹, and the linear formula 5n gives 5, 10, 15, 20. In the same way 3n gives 3, 6, 9, 12 for 3, 6, 12, 24. For 2, 4, 8, 16 the nth term is 2ⁿ, because the first term is 2¹, the second 2², and so on.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-doubling-next-term  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence begins 5, 10, 20, 40, … What is the next term?', 'Each term is double the one before, so 40 doubles to 80. 45 assumes each term goes up by 5, and 60 assumes it goes up by 20. 70 carries on the differences 5, 10, 20 with a further 30, which fits the first few terms but not the pattern. A sequence does not have to increase by the same amount every time, and here it does not.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-square-numbers  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'The sequence 1, 4, 9, 16, 25, … has which nth term?', 'These are the square numbers: 1 = 1², 4 = 2², 9 = 3², 16 = 4². The differences between the terms grow (3, 5, 7), which is a sign of a square rule rather than a linear one. 2n gives the even numbers, 2n − 1 gives the odd numbers, and n² + 1 gives 2, 5, 10, which is one ahead of each term.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tick-rules  (band 4, multi_select)
values ((select id from topics where slug = 'sequences'), 'Tick every statement that is true.', '1 + 1 = 2, 1 + 2 = 3, 2 + 3 = 5 and so on, so the rule adds the two previous terms; doubling would give 1, 2, 4, 8. 2, 4, 6, 8 goes up by 2 and 1, 4, 7, 10 goes up by 3. Not every sequence is like that: a sequence only has to follow some rule, and doubling, squaring and adding the previous terms are all allowed.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-tenth-from-fifth  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'In a sequence the 5th term is 16 and the terms increase by 4 each time. What is the 10th term?', 'From the 5th term to the 10th is five steps, so add 5 × 4 = 20 to 16, giving 36. Doubling the 5th term gives 32, which assumes the 10th is twice the 5th. Adding 4 six times to 16 gives 40, one step too many. Adding a single 4 gives 20.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-is-100-a-term  (band 4, single_choice)
values ((select id from topics where slug = 'sequences'), 'Is 100 a term of the sequence 4, 7, 10, 13, …?', 'The nth term is 3n + 1. Solving 3n + 1 = 100 gives 3n = 99 and n = 33, so 100 is the 33rd term. The sequence alternates even and odd (4, 7, 10, 13), so it is not all odd; and the terms are one more than a multiple of 3 (4 = 3 + 1, 7 = 6 + 1), not one less. 25 × 4 = 100 is not how the sequence grows.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-decreasing-nth-term  (band 4, single_choice)
values ((select id from topics where slug = 'sequences'), 'What is the nth term of 20, 17, 14, 11, …?', 'The terms go down by 3, so the formula contains −3n. At n = 1, −3n = −3 and the first term is 20, so add 23: 23 − 3n. 3n + 23 increases instead of decreasing. 20 − 3n gives 17, 14, 11, missing the first term. 3n − 23 gives −20, −17, −14, which are negative.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-tick-decreasing  (band 4, multi_select)
values ((select id from topics where slug = 'sequences'), 'Tick every statement that is true.', 'For a decreasing sequence the coefficient of n is negative. 20, 17, 14 has −3n and needs +23 to start at 20; 100, 90, 80 has −10n and needs +110. Using +3n or +10n makes the sequence grow instead. There is no rule that a sequence must increase; it can go down or change direction.', 4, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-missing-term  (band 1, single_choice)
values ((select id from topics where slug = 'sequences'), 'A sequence is 4, 9, 14, __, 24, … What is the missing term?', 'The terms increase by 5 each time, so the missing term is 14 + 5 = 19, and 19 + 5 = 24 checks it. 18, 20 and 16 do not fit the pattern: from 14, they would not leave a gap of 5 to the next term.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-fourth-term-formula  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'The nth term of a sequence is 5n − 2. What is the 4th term?', 'Substitute n = 4: 5 × 4 − 2 = 18. Writing 20 forgets to subtract the 2. 3 is the first term, from n = 1. 22 comes from adding the 2 instead of subtracting it.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-bridge-tile-rows  (band 2, single_choice)
values ((select id from topics where slug = 'sequences'), 'A tile pattern has 3 tiles in row 1, 5 tiles in row 2, 7 tiles in row 3, and so on. How many tiles are in row 10?', 'Rows go up by 2, so the nth term is 2n + 1. For row 10 that is 2 × 10 + 1 = 21. Using only the doubling step, 2n, gives 20 without the extra 1. 23 uses 2n + 3 and 19 uses 2n − 1; each is one step out from the correct formula.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- seq-retention-terminology  (band 1, multi_select)
values ((select id from topics where slug = 'sequences'), 'Tick every statement that is true.', 'Counting starts at the 1st term, which is 2. The terms are 2, 4, 6, 8, so the 3rd is 6 and the 4th is 8. Each term is 2 more than the one before, which is the term-to-term rule. Calling the 4th term 6 counts from zero and lands one place early.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- seq-error-nth-term  (band 3, single_choice)
values ((select id from topics where slug = 'sequences'), 'Dan says the nth term of 4, 7, 10, 13, … is n + 3. What has he done?', 'The term-to-term rule is ''add 3'', which describes how to get from one term to the next; it is not the nth term. The nth term is 3n + 1, which gives 4, 7, 10, 13 when you substitute n = 1, 2, 3, 4. Starting at n = 0, subtracting instead of adding, or multiplying the first term by n would all give different sequences.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-tick-line-from-points  (band 2, multi_select)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A straight line passes through (0, −2), (1, 1) and (2, 4). Tick every statement that is true.', 'y rises by 3 each time x rises by 1, so the equation is y = 3x + c; at x = 0 the value is −2, so y = 3x − 2. Adding the y-step to x instead of multiplying gives y = x + 3. Substituting x = 4 gives y = 3 × 4 − 2 = 10. The line crosses the y-axis at (0, −2), not at the origin.', 2, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- grph-table-to-equation  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A straight line gives y = 1 when x = 0, y = 4 when x = 1, and y = 7 when x = 2. Which is its equation?', 'y increases by 3 whenever x increases by 1, so the coefficient of x is 3. At x = 0, y = 1, so the constant is +1 and the equation is y = 3x + 1. y = x + 3 adds 3 to x rather than multiplying. y = 3x would cross at the origin, and y = 3x − 1 would give y = −1 at x = 0.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-gradient-and-intercept  (band 3, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'For the line y = 5x − 3, what is the gradient and where does it cross the y-axis?', 'In y = mx + c the number multiplying x is the gradient and the constant is the y-intercept, so the gradient is 5 and the line crosses the y-axis at −3. Swapping the two, or taking the gradient as −3, confuses the gradient with the intercept. Changing the sign of the intercept puts the crossing on the wrong side of the origin. 1/5 is the reciprocal of the gradient.', 3, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-crossing-at-4  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which line crosses the y-axis at (0, 4)?', 'A line crosses the y-axis where x = 0, so the crossing point is the constant term. y = 2x + 4 gives y = 4 at x = 0. y = 4x + 2 crosses at 2, and the 4 is the gradient. y = 4x crosses at the origin, and y = x + 2 crosses at 2 as well.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-coordinates-direction  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'What are the coordinates of the point 3 to the right and 2 down from the origin?', 'Coordinates are written (x, y): the x value comes first and tells you how far right, and the y value second and tells you how far up. So 3 right and 2 down is (3, −2). The other options put the numbers the wrong way round or use the wrong signs.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-tick-coordinates  (band 1, multi_select)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Tick every statement that is true.', 'The first coordinate is x and the second is y, so (4, −1) is 4 right and 1 down, while (−1, 4) is 1 left and 4 up. A point lies on the y-axis when x = 0, so (0, 3) does and (3, 0) lies on the x-axis. Both (−2, −5) and (−1, −3) have two negative coordinates, so they are in the same region, the bottom-left.', 1, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- grph-gradient-from-two-points  (band 2, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A line passes through (1, 2) and (4, 11). What is its gradient?', 'Gradient is the rise divided by the run: y goes up by 11 − 2 = 9 and x goes up by 4 − 1 = 3, so the gradient is 9 ÷ 3 = 3. Writing 1/3 turns the fraction the wrong way up. 9 is the rise on its own, without dividing by the run, and 6 comes from subtracting the run from the rise (9 − 3).', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-negative-gradient  (band 4, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'A line passes through (0, 5) and (2, 1). What is its gradient?', 'y changes by 1 − 5 = −4 and x changes by 2 − 0 = 2, so the gradient is −4 ÷ 2 = −2. The line goes downhill, so the gradient must be negative; 2 drops the sign. −1/2 turns the division the wrong way up, and 4 is the change in y on its own.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-midpoint  (band 2, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'On a map, a straight path runs from the point (2, 3) to the point (8, 11). A bench sits exactly half way along the path. What are the coordinates of the bench?', 'The midpoint is the average of the coordinates: ((2 + 8) ÷ 2, (3 + 11) ÷ 2) = (5, 7). (6, 8) is the difference between the points, halved. (10, 14) adds the coordinates without dividing, and (3, 4) halves each coordinate of the second point.', 2, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-tick-midpoint  (band 3, multi_select)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Tick every statement that is true.', 'Average the coordinates: (0 + 4) ÷ 2 = 2 and (0 + 6) ÷ 2 = 3; (−2 + 4) ÷ 2 = 1 and (1 + 5) ÷ 2 = 3; (2 + 2) ÷ 2 = 2 and (3 + 7) ÷ 2 = 5. Leaving the coordinates unchanged, or using the differences (3, 2), does not give the half-way point.', 3, 'PUBLISHED', 'SEED', 'MULTI_SELECT', 8);
delete from seed_question;
-- grph-point-on-line  (band 4, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which of these points lies on the line y = 2x + 1?', 'Substitute the x value and check the y value: 2 × 1.5 + 1 = 4, so (1.5, 4) is on the line. A line passes through points with any coordinates, not only whole numbers, so rejecting (1.5, 4) is a mistake. (2, 4) would need y = 5, (1, 4) would need y = 3, and (3, 4) would need y = 7.', 4, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
-- grph-horizontal-line  (band 1, single_choice)
values ((select id from topics where slug = 'coordinates-and-linear-graphs'), 'Which of these lines is horizontal?', 'y = 4 means every point on the line has y-value 4, whatever x is, so it runs left to right and is horizontal. x = 4 means every point has x-value 4, which runs up and down and is vertical; x = 0 is the y-axis, also vertical. y = 4x is a sloping line through the origin with gradient 4.', 1, 'PUBLISHED', 'SEED', 'SINGLE_CHOICE', 8);
delete from seed_question;
